const express = require('express');
const app = express();

app.use(express.json());

// Safe rule evaluator.
//
// NOTE: The reference implementation in docs/RULES_ENGINE.md uses
// `Function(...)` / dynamic eval on a caller-supplied string. That is a
// critical RCE vulnerability (arbitrary code execution on the server from
// untrusted input) and is intentionally NOT used here.
//
// Instead we support a small, well-defined expression grammar:
//   <field> <op> <value>
// where:
//   - <field> is a dotted path into the request context (e.g. "amount",
//     "user.role"), restricted to the `context` object only.
//   - <op> is one of: == != > >= < <= (=== / !== also accepted)
//   - <value> is a JSON literal (number, quoted string, true/false/null)
//
// Optionally, multiple comparisons can be combined with && or ||.
const COMPARATORS = {
  '===': (a, b) => a === b,
  '!==': (a, b) => a !== b,
  '==': (a, b) => a === b,
  '!=': (a, b) => a !== b,
  '>=': (a, b) => a >= b,
  '<=': (a, b) => a <= b,
  '>': (a, b) => a > b,
  '<': (a, b) => a < b,
};

function getPath(obj, path) {
  return path.split('.').reduce((acc, key) => {
    if (acc == null) return undefined;
    // Block prototype-pollution / escape attempts.
    if (key === '__proto__' || key === 'constructor' || key === 'prototype') {
      throw new Error('Forbidden field path');
    }
    return acc[key];
  }, obj);
}

function parseValue(raw) {
  const token = raw.trim();
  // JSON.parse handles numbers, booleans, null, and double-quoted strings.
  try {
    return JSON.parse(token);
  } catch (_) {
    // Allow single-quoted strings as a convenience.
    if (
      (token.startsWith("'") && token.endsWith("'")) ||
      (token.startsWith('"') && token.endsWith('"'))
    ) {
      return token.slice(1, -1);
    }
    throw new Error('Invalid literal value: ' + token);
  }
}

function evalComparison(expr, context) {
  // Match: field <op> value
  const opPattern = /\s*(===|!==|==|!=|>=|<=|>|<)\s*/;
  const match = expr.match(opPattern);
  if (!match) {
    throw new Error('Invalid comparison: ' + expr);
  }
  const op = match[1];
  const idx = match.index;
  const field = expr.slice(0, idx).trim();
  const valueRaw = expr.slice(idx + match[0].length);

  if (!/^[A-Za-z_][A-Za-z0-9_.]*$/.test(field)) {
    throw new Error('Invalid field reference: ' + field);
  }

  const left = getPath(context, field);
  const right = parseValue(valueRaw);
  return COMPARATORS[op](left, right);
}

// Evaluate a caller-supplied rule expression safely against the context.
function evalRule(req) {
  const expr = req.body && req.body.rule;
  if (typeof expr !== 'string') {
    throw new Error('Missing or invalid "rule" expression');
  }
  const context = (req.body && req.body.context) || {};

  // Support top-level && / || combinations of comparisons.
  const orParts = expr.split('||');
  return orParts.some((orPart) =>
    orPart.split('&&').every((andPart) => evalComparison(andPart.trim(), context))
  );
}

