const express = require('express');
const app = express();

app.use(express.json());

// Safe rule evaluator.
//
// NOTE: The reference in docs/RULES_ENGINE.md uses `Function(...)`/eval on a
// caller-supplied string. That is a remote code execution vulnerability and is
// intentionally NOT used here. Instead we parse and evaluate a restricted
// expression grammar that covers the documented use case (e.g. `ctx.amount > 100`):
//   - operands: numbers, quoted strings, booleans, null, or `ctx.<dotted.path>`
//   - comparisons: ==, !=, ===, !==, <, <=, >, >=
//   - boolean logic: && , || , and parentheses
// No function calls, property writes, or arbitrary code are permitted.

function resolvePath(ctx, path) {
  // path like "ctx.amount" or "ctx.user.role"
  const parts = path.split('.');
  if (parts[0] !== 'ctx') {
    throw new Error(`Unsupported identifier: ${path}`);
  }
  let cur = ctx;
  for (let i = 1; i < parts.length; i++) {
    if (cur == null) return undefined;
    cur = cur[parts[i]];
  }
  return cur;
}

function tokenize(expr) {
  const tokens = [];
  const re =
    /\s*(?:(&&|\|\||===|!==|==|!=|<=|>=|<|>)|(\()|(\))|("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*')|(-?\d+(?:\.\d+)?)|(true|false|null)|(ctx(?:\.[A-Za-z_$][A-Za-z0-9_$]*)+))/g;
  let lastIndex = 0;
  let m;
  while ((m = re.exec(expr)) !== null) {
    if (m.index !== lastIndex) {
      throw new Error(`Unexpected token near: ${expr.slice(lastIndex)}`);
    }
    lastIndex = re.lastIndex;
    if (m[1]) tokens.push({ type: 'op', value: m[1] });
    else if (m[2]) tokens.push({ type: 'lparen' });
    else if (m[3]) tokens.push({ type: 'rparen' });
    else if (m[4] !== undefined) tokens.push({ type: 'value', value: JSON.parse(m[4].replace(/^'|'$/g, '"')) });
    else if (m[5] !== undefined) tokens.push({ type: 'value', value: Number(m[5]) });
    else if (m[6]) tokens.push({ type: 'value', value: m[6] === 'true' ? true : m[6] === 'false' ? false : null });
    else if (m[7]) tokens.push({ type: 'path', value: m[7] });
  }
  if (lastIndex !== expr.length && expr.slice(lastIndex).trim() !== '') {
    throw new Error(`Unexpected token near: ${expr.slice(lastIndex)}`);
  }
  return tokens;
}

// Recursive-descent parser/evaluator: orExpr -> andExpr -> comparison -> primary
function evaluateExpression(expr, ctx) {
  const tokens = tokenize(expr);
  let pos = 0;

  const peek = () => tokens[pos];
  const next = () => tokens[pos++];

  function parsePrimary() {
    const t = next();
    if (!t) throw new Error('Unexpected end of expression');
    if (t.type === 'lparen') {
      const v = parseOr();
      const close = next();
      if (!close || close.type !== 'rparen') throw new Error('Expected )');
      return v;
    }
    if (t.type === 'value') return t.value;
    if (t.type === 'path') return resolvePath(ctx, t.value);
    throw new Error(`Unexpected token: ${JSON.stringify(t)}`);
  }

  function parseComparison() {
    let left = parsePrimary();
    while (peek() && peek().type === 'op' && !['&&', '||'].includes(peek().value)) {
      const op = next().value;
      const right = parsePrimary();
      switch (op) {
        case '==': left = left == right; break; // eslint-disable-line eqeqeq
        case '!=': left = left != right; break; // eslint-disable-line eqeqeq
        case '===': left = left === right; break;
        case '!==': left = left !== right; break;
        case '<': left = left < right; break;
        case '<=': left = left <= right; break;
        case '>': left = left > right; break;
        case '>=': left = left >= right; break;
        default: throw new Error(`Unsupported operator: ${op}`);
      }
    }
    return left;
  }

  function parseAnd() {
    let left = parseComparison();
    while (peek() && peek().type === 'op' && peek().value === '&&') {
      next();
      const right = parseComparison();
      left = left && right;
    }
    return left;
  }

  function parseOr() {
    let left = parseAnd();
    while (peek() && peek().type === 'op' && peek().value === '||') {
      next();
      const right = parseAnd();
      left = left || right;
    }
    return left;
  }

  const result = parseOr();
  if (pos !== tokens.length) throw new Error('Trailing tokens in expression');
  return result;
}

