const express = require('express');
const app = express();

app.use(express.json());

// Safe rule evaluator.
//
// NOTE: The reference in docs/RULES_ENGINE.md uses `Function(...)` / dynamic
// eval on caller-supplied input. That is a critical RCE vulnerability and is
// intentionally NOT used here. Instead, rules are expressed as a small,
// declarative AST that supports the same intent (comparing context values)
// without ever executing arbitrary code.
//
// Rule shape examples:
//   { "op": ">",  "field": "amount", "value": 100 }
//   { "op": "==", "field": "country", "value": "US" }
//   { "op": "and", "rules": [ <rule>, <rule> ] }
//   { "op": "or",  "rules": [ <rule>, <rule> ] }
//   { "op": "not", "rule": <rule> }

const COMPARATORS = {
  '==': (a, b) => a === b,
  '!=': (a, b) => a !== b,
  '>': (a, b) => a > b,
  '>=': (a, b) => a >= b,
  '<': (a, b) => a < b,
  '<=': (a, b) => a <= b,
  in: (a, b) => Array.isArray(b) && b.includes(a),
};

// Safely read a dotted path (e.g. "user.role") from the context object.
function getField(ctx, field) {
  if (typeof field !== 'string') {
    throw new Error('field must be a string');
  }
  return field.split('.').reduce((obj, key) => {
    if (obj == null || typeof obj !== 'object') return undefined;
    // Block prototype-pollution / sandbox-escape style access.
    if (key === '__proto__' || key === 'constructor' || key === 'prototype') {
      throw new Error(`illegal field segment: ${key}`);
    }
    return obj[key];
  }, ctx);
}

function evalRule(rule, ctx, depth = 0) {
  if (depth > 50) throw new Error('rule nesting too deep');
  if (!rule || typeof rule !== 'object') {
    throw new Error('rule must be an object');
  }

  switch (rule.op) {
    case 'and':
      if (!Array.isArray(rule.rules)) throw new Error('"and" requires rules[]');
      return rule.rules.every((r) => evalRule(r, ctx, depth + 1));
    case 'or':
      if (!Array.isArray(rule.rules)) throw new Error('"or" requires rules[]');
