// Safe rule evaluator.
//
// NOTE: docs/RULES_ENGINE.md suggests using `Function(...)`/eval on the
// caller-supplied `rule` string. That would allow arbitrary remote code
// execution (e.g. a request body of
//   { "rule": "require('child_process').execSync('...')" }
// would run on the server). We deliberately do NOT do that.
//
// Instead we implement a small, sandboxed expression language that supports
// the documented use cases (e.g. `ctx.amount > 100`) without exposing any
// JS runtime capabilities. The evaluator can only read values from the
// provided context; it cannot call functions or reach globals.

// ---- Tokenizer ----
const TOKEN_RE =
  /\s*(>=|<=|===|!==|==|!=|&&|\|\||[<>()+\-*/%!]|true\b|false\b|null\b|"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|[0-9]+(?:\.[0-9]+)?|[A-Za-z_$][A-Za-z0-9_$.]*)/y;

function tokenize(expr) {
  const tokens = [];
  let i = 0;
  while (i < expr.length) {
    if (/\s/.test(expr[i])) { i++; continue; }
    TOKEN_RE.lastIndex = i;
    const m = TOKEN_RE.exec(expr);
    if (!m || m.index !== i) {
      throw new Error(`Invalid token in rule at position ${i}`);
    }
    tokens.push(m[1]);
    i = TOKEN_RE.lastIndex;
  }
  return tokens;
}

// ---- Parser (recursive descent) -> AST ----
// Grammar (lowest to highest precedence):
//   or   := and ('||' and)*
//   and  := eq  ('&&' eq)*
//   eq   := cmp (('==' | '!=' | '===' | '!==') cmp)*
//   cmp  := add (('<' | '>' | '<=' | '>=') add)*
//   add  := mul (('+' | '-') mul)*
//   mul  := unary (('*' | '/' | '%') unary)*
//   unary:= ('!' | '-') unary | primary
//   primary := number | string | bool | null | identifier | '(' or ')'
function parse(tokens) {
  let pos = 0;
  const peek = () => tokens[pos];
  const next = () => tokens[pos++];
  const expect = (t) => {
    if (next() !== t) throw new Error(`Expected '${t}' in rule`);
  };

  function parseOr() {
    let node = parseAnd();
    while (peek() === '||') { next(); node = { type: 'logical', op: '||', left: node, right: parseAnd() }; }
    return node;
  }
  function parseAnd() {
    let node = parseEq();
    while (peek() === '&&') { next(); node = { type: 'logical', op: '&&', left: node, right: parseEq() }; }
    return node;
  }
  function parseEq() {
    let node = parseCmp();
    while (['==', '!=', '===', '!=='].includes(peek())) {
      const op = next();
      node = { type: 'binary', op, left: node, right: parseCmp() };
    }
    return node;
  }
  function parseCmp() {
    let node = parseAdd();
    while (['<', '>', '<=', '>='].includes(peek())) {
      const op = next();
      node = { type: 'binary', op, left: node, right: parseAdd() };
    }
    return node;
  }
  function parseAdd() {
    let node = parseMul();
    while (peek() === '+' || peek() === '-') {
      const op = next();
      node = { type: 'binary', op, left: node, right: parseMul() };
    }
    return node;
  }
  function parseMul() {
    let node = parseUnary();
    while (['*', '/', '%'].includes(peek())) {
      const op = next();
      node = { type: 'binary', op, left: node, right: parseUnary() };
    }
    return node;
  }
  function parseUnary() {
    if (peek() === '!' || peek() === '-') {
      const op = next();
      return { type: 'unary', op, arg: parseUnary() };
    }
    return parsePrimary();
  }
  function parsePrimary() {
    const t = next();
    if (t === undefined) throw new Error('Unexpected end of rule');
    if (t === '(') {
      const node = parseOr();
      expect(')');
      return node;
    }
    if (/^[0-9]/.test(t)) return { type: 'literal', value: Number(t) };
    if ((t[0] === '"' || t[0] === "'")) {
      return { type: 'literal', value: JSON.parse('"' + t.slice(1, -1).replace(/\\?"/g, '\\"') + '"') };
    }
    if (t === 'true') return { type: 'literal', value: true };
    if (t === 'false') return { type: 'literal', value: false };
    if (t === 'null') return { type: 'literal', value: null };
    if (/^[A-Za-z_$][A-Za-z0-9_$.]*$/.test(t)) {
      return { type: 'identifier', path: t.split('.') };
    }
    throw new Error(`Unexpected token '${t}' in rule`);
  }

  const ast = parseOr();
  if (pos !== tokens.length) throw new Error(`Unexpected token '${tokens[pos]}' in rule`);
  return ast;
}

// ---- Evaluator ----
function resolvePath(path, scope) {
  let cur = scope;
  for (const key of path) {
    if (cur == null) return undefined;
    // Only own/visible properties on plain data; never reach prototype tricks.
    if (key === '__proto__' || key === 'constructor' || key === 'prototype') {
      throw new Error('Forbidden property access in rule');
    }
    cur = cur[key];
  }
  return cur;
}

function evaluate(node, scope) {
  switch (node.type) {
    case 'literal':
      return node.value;
    case 'identifier':
      return resolvePath(node.path, scope);
    case 'unary': {
      const v = evaluate(node.arg, scope);
      return node.op === '!' ? !v : -v;
    }
    case 'logical': {
      const l = evaluate(node.left, scope);
      if (node.op === '&&') return l && evaluate(node.right, scope);
      return l || evaluate(node.right, scope);
    }
    case 'binary': {
      const l = evaluate(node.left, scope);
      const r = evaluate(node.right, scope);
      switch (node.op) {
        case '==': return l == r; // eslint-disable-line eqeqeq
        case '!=': return l != r; // eslint-disable-line eqeqeq
        case '===': return l === r;
        case '!==': return l !== r;
        case '<': return l < r;
        case '>': return l > r;
        case '<=': return l <= r;
        case '>=': return l >= r;
        case '+': return l + r;
        case '-': return l - r;
        case '*': return l * r;
        case '/': return l / r;
        case '%': return l % r;
        default: throw new Error(`Unknown operator '${node.op}'`);
      }
    }
    default:
      throw new Error('Unknown AST node');
  }
}

const MAX_RULE_LENGTH = 1000;

/**
 * Safely evaluate a rule expression against a context.
 * @param {string} rule - e.g. "ctx.amount > 100 && ctx.country === 'US'"
 * @param {object} context - arbitrary plain-data context
 * @returns {boolean} coerced truthiness of the rule result
 */
function evalRule(rule, context) {
  if (typeof rule !== 'string') {
    throw new Error('rule must be a string');
  }
  if (rule.length > MAX_RULE_LENGTH) {
    throw new Error('rule is too long');
  }
  const ast = parse(tokenize(rule));
  const scope = { ctx: context };
  return Boolean(evaluate(ast, scope));
}

module.exports = { evalRule };

