//   - grouping:               ( ... )
//
// No function calls, no property access on built-ins, no assignment.
// ---------------------------------------------------------------------------

function tokenize(input) {
  const tokens = [];
  const re = /\s*(>=|<=|===|!==|==|!=|&&|\|\||[<>!()]|"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|[A-Za-z_$][A-Za-z0-9_$.]*|-?\d+(?:\.\d+)?)/y;
  let m;
  let lastIndex = 0;
  while (lastIndex < input.length) {
    re.lastIndex = lastIndex;
    m = re.exec(input);
    if (!m || m.index !== lastIndex) {
      // skip pure trailing whitespace, otherwise error
      if (/^\s*$/.test(input.slice(lastIndex))) break;
      throw new Error(`Unexpected token near: "${input.slice(lastIndex, lastIndex + 16)}"`);
    }
    tokens.push(m[1]);
    lastIndex = re.lastIndex;
  }
  return tokens;
}

function parse(tokens) {
  let pos = 0;
  const peek = () => tokens[pos];
  const next = () => tokens[pos++];
  const expect = (t) => {
    if (next() !== t) throw new Error(`Expected "${t}"`);
  };

  // Grammar (lowest to highest precedence): || , && , comparison , unary , primary
  function parseOr() {
    let left = parseAnd();
    while (peek() === '||') {
      next();
      left = { type: 'logical', op: '||', left, right: parseAnd() };
    }
    return left;
  }
  function parseAnd() {
    let left = parseComparison();
    while (peek() === '&&') {
      next();
      left = { type: 'logical', op: '&&', left, right: parseComparison() };
    }
    return left;
  }
  function parseComparison() {
    let left = parseUnary();
    const cmp = ['==', '!=', '===', '!==', '>', '>=', '<', '<='];
    while (cmp.includes(peek())) {
      const op = next();
      left = { type: 'compare', op, left, right: parseUnary() };
    }
    return left;
  }
  function parseUnary() {
    if (peek() === '!') {
      next();
      return { type: 'not', arg: parseUnary() };
    }
    return parsePrimary();
  }
  function parsePrimary() {
    const t = peek();
    if (t === '(') {
      next();
      const e = parseOr();
      expect(')');
      return e;
    }
    if (t === undefined) throw new Error('Unexpected end of expression');
    next();
