{
  "name": "acme-rules",
  "version": "1.0.0",
  "description": "Dynamic rule engine with a safe, sandboxed expression evaluator",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "test": "node test/check.test.js"
  },
  "dependencies": {
    "express": "^4.19.2",
    "expr-eval": "^2.0.2"
  }
}

// Safe expression evaluator for the rule engine.
//
// SECURITY NOTE:
// The reference implementation in docs/RULES_ENGINE.md uses
// `Function('ctx','req', 'return (' + expr + ');')` on a caller-supplied
// string. That is arbitrary remote code execution (RCE): a client could send
// a "rule" like `require('child_process').execSync('...')` or read
// `process.env` secrets. We intentionally do NOT do that.
//
// Instead, this module parses the rule into an AST limited to:
//   - literals: numbers, strings, true/false/null
//   - identifiers / member access (read-only) against a provided context
//   - operators: + - * / %, comparisons, && || !, parentheses
//   - array/object index access via dot or [ "key" ]
// No function calls, no assignment, no access to globals, process, require, etc.

const TOKEN = /\s*(=>|===|!==|==|!=|<=|>=|&&|\|\||[<>]|[-+*/%()[\].!]|"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|\d+(?:\.\d+)?|[A-Za-z_$][A-Za-z0-9_$]*)/y;

function tokenize(src) {
  const tokens = [];
  TOKEN.lastIndex = 0;
  let m;
  let lastIndex = 0;
  while (lastIndex < src.length) {
    TOKEN.lastIndex = lastIndex;
    m = TOKEN.exec(src);
    if (!m || m.index !== lastIndex) {
      // allow trailing whitespace
      if (/^\s*$/.test(src.slice(lastIndex))) break;
      throw new SyntaxError(`Unexpected token near: ${src.slice(lastIndex, lastIndex + 20)}`);
    }
    tokens.push(m[1]);
    lastIndex = TOKEN.lastIndex;
  }
  return tokens;
}

// Recursive-descent parser -> evaluator. Returns a function (ctx) => value.
function parse(src) {
  const tokens = tokenize(src);
  let pos = 0;

  const peek = () => tokens[pos];
  const next = () => tokens[pos++];
  const expect = (t) => {
    if (tokens[pos] !== t) throw new SyntaxError(`Expected '${t}' but got '${tokens[pos] ?? 'EOF'}'`);
    pos++;
  };

  // Precedence climbing for binary operators.
  const BINOPS = {
    '||': { prec: 1, fn: (a, b) => a() || b() },
    '&&': { prec: 2, fn: (a, b) => a() && b() },
    '==': { prec: 3, fn: (a, b) => a() == b() }, // eslint-disable-line eqeqeq
    '!=': { prec: 3, fn: (a, b) => a() != b() }, // eslint-disable-line eqeqeq
    '===': { prec: 3, fn: (a, b) => a() === b() },
    '!==': { prec: 3, fn: (a, b) => a() !== b() },
    '<': { prec: 4, fn: (a, b) => a() < b() },
    '>': { prec: 4, fn: (a, b) => a() > b() },
    '<=': { prec: 4, fn: (a, b) => a() <= b() },
    '>=': { prec: 4, fn: (a, b) => a() >= b() },
    '+': { prec: 5, fn: (a, b) => a() + b() },
    '-': { prec: 5, fn: (a, b) => a() - b() },
    '*': { prec: 6, fn: (a, b) => a() * b() },
    '/': { prec: 6, fn: (a, b) => a() / b() },
    '%': { prec: 6, fn: (a, b) => a() % b() },
  };

  function parseExpression(minPrec = 0) {
    let left = parseUnary();
    while (true) {
      const op = peek();
      const info = BINOPS[op];
      if (!info || info.prec < minPrec) break;
      next();
      const right = parseExpression(info.prec + 1);
      const l = left;
      // Short-circuit operators must defer evaluation; wrap as thunks.
      left = (ctx) => info.fn(() => l(ctx), () => right(ctx));
    }
    return left;
  }

  function parseUnary() {
    const t = peek();
    if (t === '!') {
      next();
      const operand = parseUnary();
      return (ctx) => !operand(ctx);
    }
    if (t === '-') {
      next();
      const operand = parseUnary();
      return (ctx) => -operand(ctx);
    }
    if (t === '+') {
      next();
      return parseUnary();
    }
    return parsePostfix();
  }

  function parsePostfix() {
    let node = parsePrimary();
    while (true) {
      const t = peek();
      if (t === '.') {
        next();
        const name = next();
        if (!/^[A-Za-z_$][A-Za-z0-9_$]*$/.test(name || '')) {
          throw new SyntaxError(`Invalid property name '${name}'`);
        }
        const obj = node;
        node = (ctx) => readProp(obj(ctx), name);
      } else if (t === '[') {
        next();
        const idx = parseExpression();
        expect(']');
        const obj = node;
        node = (ctx) => readProp(obj(ctx), idx(ctx));
      } else {
        break;
      }
    }
    return node;
  }

  function parsePrimary() {
    const t = next();
    if (t === undefined) throw new SyntaxError('Unexpected end of expression');
    if (t === '(') {
      const e = parseExpression();
      expect(')');
      return e;
    }
    if (/^\d/.test(t)) {
      const n = Number(t);
      return () => n;
    }
    if (t[0] === '"' || t[0] === "'") {
      const s = JSON.parse(t[0] === "'" ? `"${t.slice(1, -1).replace(/"/g, '\\"')}"` : t);
      return () => s;
    }
    if (t === 'true') return () => true;
    if (t === 'false') return () => false;
    if (t === 'null') return () => null;
    if (/^[A-Za-z_$][A-Za-z0-9_$]*$/.test(t)) {
      // Root identifier: must exist on the sandboxed context.
      return (ctx) => readProp(ctx, t);
    }
    throw new SyntaxError(`Unexpected token '${t}'`);
  }

  const evaluator = parseExpression();
  if (pos !== tokens.length) {
    throw new SyntaxError(`Unexpected token '${tokens[pos]}'`);
  }
  return evaluator;
}

// Property access that refuses prototype-pollution / escape vectors.
const FORBIDDEN = new Set([
  '__proto__', 'prototype', 'constructor',
]);

function readProp(obj, key) {
  if (obj == null) return undefined;
  const k = String(key);
  if (FORBIDDEN.has(k)) {
    throw new Error(`Access to '${k}' is not allowed`);
  }
  // Only allow own/enumerable data access; never traverse into functions.
  const val = obj[k];
  if (typeof val === 'function') {
    throw new Error(`Calling or accessing functions ('${k}') is not allowed`);
  }
  return val;
}

// Public API: compile once, evaluate against a plain context object.
function compileRule(expr) {
  if (typeof expr !== 'string' || expr.trim() === '') {
    throw new SyntaxError('rule must be a non-empty string');
  }
  if (expr.length > 1000) {
    throw new SyntaxError('rule is too long');
  }
  return parse(expr);
}

function evalRuleSafe(expr, context) {
  const compiled = compileRule(expr);
  // The sandbox: the expression can only see `ctx`. No req, process, globals.
  const sandbox = { ctx: context ?? {} };
  return Boolean(compiled(sandbox));
}

module.exports = { compileRule, evalRuleSafe };

