const assert = require('assert');
const { evalRuleSafe } = require('../ruleEngine');

function ok(expr, ctx, expected) {
  const got = evalRuleSafe(expr, ctx);
  assert.strictEqual(got, expected, `${expr} => ${got}, expected ${expected}`);
}

function throws(expr, ctx) {
  assert.throws(() => evalRuleSafe(expr, ctx), `expected '${expr}' to throw`);
}

// --- Legitimate rule evaluation ---
ok('ctx.amount > 100', { amount: 150 }, true);
ok('ctx.amount > 100', { amount: 50 }, false);
ok('ctx.amount >= 100 && ctx.country == "US"', { amount: 100, country: 'US' }, true);
ok('ctx.amount > 100 || ctx.vip', { amount: 5, vip: true }, true);
ok('!ctx.blocked', { blocked: false }, true);
ok('ctx.tier == "gold" || ctx.tier == "platinum"', { tier: 'platinum' }, true);
ok('(ctx.a + ctx.b) * 2 == 10', { a: 2, b: 3 }, true);
ok('ctx.items[0] == "apple"', { items: ['apple', 'pear'] }, true);
ok('ctx.nested.flag === true', { nested: { flag: true } }, true);

// --- RCE / escape attempts must NOT execute; they error or evaluate to nothing dangerous ---
throws('constructor.constructor("return process")().env', {});
throws('ctx.constructor', { x: 1 });
throws('ctx.__proto__', { x: 1 });
throws('process.exit(1)', {}); // 'process' identifier resolves to undefined prop -> readProp on undefined returns undefined, but .exit access on undefined -> false-y, then call... ensure no call syntax
throws('require("fs")', {});
throws('ctx.toString()', { x: 1 });

