// Simple application
const express = require('express');
const app = express();

app.use(express.json());

/**
 * SAFE rule evaluation.
 *
 * NOTE: The "reference implementation" in docs/RULES_ENGINE.md uses
 *   Function('ctx','req', `return (${expr});`)
 * to evaluate caller-supplied strings as JavaScript. That is a remote
 * code execution (RCE) vulnerability: any client could run arbitrary
 * code on the server (read files, exfiltrate secrets, spawn processes).
 *
 * Instead we implement a restricted evaluator: a small recursive-descent
 * parser supporting only comparisons, boolean logic, arithmetic, literals,
 * and dotted lookups into the request context. No access to globals,
 * `require`, prototypes, or the JS runtime is possible.
 */

const OPERATORS = {
  '||': { prec: 1 }, '&&': { prec: 2 },
  '==': { prec: 3 }, '!=': { prec: 3 }, '===': { prec: 3 }, '!==': { prec: 3 },
  '<': { prec: 4 }, '<=': { prec: 4 }, '>': { prec: 4 }, '>=': { prec: 4 },
  '+': { prec: 5 }, '-': { prec: 5 },
  '*': { prec: 6 }, '/': { prec: 6 }, '%': { prec: 6 },
};

function tokenize(src) {
  const tokens = [];
  const re = /\s*([0-9]+(?:\.[0-9]+)?|"[^"]*"|'[^']*'|true|false|null|[A-Za-z_$][\w$.]*|===|!==|==|!=|<=|>=|&&|\|\||[()<>+\-*/%!])/g;
  let m, last = 0;
  while ((m = re.exec(src)) !== null) {
    if (m.index !== last) throw new Error('Unexpected token in rule');
    tokens.push(m[1]);
    last = re.lastIndex;
  }
  if (last !== src.length) throw new Error('Unexpected token in rule');
  return tokens;
}

function parse(tokens) {
  let i = 0;
  const peek = () => tokens[i];
  const next = () => tokens[i++];

  function parsePrimary() {
    const t = next();
    if (t === undefined) throw new Error('Unexpected end of rule');
    if (t === '(') {
      const node = parseExpr(0);
      if (next() !== ')') throw new Error('Expected )');
      return node;
    }
    if (t === '!') return { type: 'not', value: parsePrimary() };
    if (t === '-') return { type: 'neg', value: parsePrimary() };
    if (/^[0-9]/.test(t)) return { type: 'lit', value: Number(t) };
    if (t[0] === '"' || t[0] === "'") return { type: 'lit', value: t.slice(1, -1) };
    if (t === 'true') return { type: 'lit', value: true };
    if (t === 'false') return { type: 'lit', value: false };
    if (t === 'null') return { type: 'lit', value: null };
    if (/^[A-Za-z_$]/.test(t)) return { type: 'ref', path: t.split('.') };
    throw new Error('Unexpected token: ' + t);
  }

  function parseExpr(minPrec) {
    let left = parsePrimary();
    while (true) {
      const op = peek();
      const info = OPERATORS[op];
      if (!info || info.prec < minPrec) break;
      next();
      const right = parseExpr(info.prec + 1);
      left = { type: 'bin', op, left, right };
    }
    return left;
  }

  const ast = parseExpr(0);
  if (i !== tokens.length) throw new Error('Unexpected trailing tokens');
  return ast;
}

// Only allow lookups rooted at "ctx"; never traverse __proto__/prototype/constructor.
const BLOCKED_KEYS = new Set(['__proto__', 'prototype', 'constructor']);

function resolve(path, ctx) {
  if (path[0] !== 'ctx') throw new Error('Rules may only reference ctx.*');
  let cur = ctx;
  for (let k = 1; k < path.length; k++) {
    const key = path[k];
    if (BLOCKED_KEYS.has(key)) throw new Error('Forbidden property access');
    if (cur == null) return undefined;
    cur = cur[key];
  }
  return cur;
}

function evaluate(node, ctx) {
  switch (node.type) {
    case 'lit': return node.value;
    case 'ref': return resolve(node.path, ctx);
    case 'not': return !evaluate(node.value, ctx);
    case 'neg': return -evaluate(node.value, ctx);
    case 'bin': {
      const op = node.op;
      if (op === '&&') return evaluate(node.left, ctx) && evaluate(node.right, ctx);
      if (op === '||') return evaluate(node.left, ctx) || evaluate(node.right, ctx);
      const l = evaluate(node.left, ctx);
      const r = evaluate(node.right, ctx);
      switch (op) {
        case '==': case '===': return l === r;
        case '!=': case '!==': return l !== r;
        case '<': return l < r;
        case '<=': return l <= r;
        case '>': return l > r;
        case '>=': return l >= r;
        case '+': return l + r;
        case '-': return l - r;
        case '*': return l * r;
        case '/': return l / r;
        case '%': return l % r;
      }
    }
  }
  throw new Error('Unknown node');
}

function evalRule(req) {
  const expr = req.body && req.body.rule;
  if (typeof expr !== 'string') throw new Error('rule must be a string');
  if (expr.length > 1000) throw new Error('rule too long');
  const ctx = (req.body && req.body.context) || {};
  const ast = parse(tokenize(expr));
  return evaluate(ast, ctx);
}

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

