// Safe rule evaluator.
//
// SECURITY NOTE: The reference implementation in docs/RULES_ENGINE.md uses
// `Function(...)` / dynamic eval on a caller-supplied string. That is arbitrary
// remote code execution against untrusted input and must NOT be shipped.
// Instead we evaluate the rule expression with a small sandboxed parser that
// only supports reading values from the request `context` plus comparison,
// boolean, and arithmetic operators. No function calls, no globals, no access
// to `req`, the filesystem, or the process.
// ---------------------------------------------------------------------------

// Tokenizer
function tokenize(src) {
  const tokens = [];
  const re = /\s*([0-9]+(?:\.[0-9]+)?|"[^"]*"|'[^']*'|[A-Za-z_$][A-Za-z0-9_$]*|>=|<=|===|!==|==|!=|&&|\|\||[()<>+\-*/%.!])\s*/g;
  let m;
  let last = 0;
  while ((m = re.exec(src)) !== null) {
    if (m.index !== last) throw new Error('Unexpected token in rule');
    tokens.push(m[1]);
    last = re.lastIndex;
  }
  if (last !== src.length) throw new Error('Unexpected token in rule');
  return tokens;
}

const KEYWORDS = { true: true, false: false, null: null };

// Recursive-descent parser producing a value. Grammar (lowest to highest prec):
// or := and ('||' and)*
// and := equality ('&&' equality)*
// equality := comparison (('=='|'!='|'==='|'!==') comparison)*
// comparison := additive (('<'|'>'|'<='|'>=') additive)*
// additive := multiplicative (('+'|'-') multiplicative)*
// multiplicative := unary (('*'|'/'|'%') unary)*
// unary := '!' unary | '-' unary | primary
// primary := number | string | bool/null | ident member-chain | '(' or ')'
function evaluate(expr, ctx) {
  const tokens = tokenize(expr);
  let i = 0;
  const peek = () => tokens[i];
  const next = () => tokens[i++];

  function parseOr() {
    let left = parseAnd();
    while (peek() === '||') { next(); const r = parseAnd(); left = left || r; }
    return left;
  }
  function parseAnd() {
    let left = parseEquality();
    while (peek() === '&&') { next(); const r = parseEquality(); left = left && r; }
    return left;
  }
  function parseEquality() {
    let left = parseComparison();
    while (['==', '!=', '===', '!=='].includes(peek())) {
      const op = next();
      const r = parseComparison();
      // eslint-disable-next-line eqeqeq
      if (op === '==' || op === '===') left = left === r;
      else left = left !== r;
    }
    return left;
  }
  function parseComparison() {
    let left = parseAdditive();
    while (['<', '>', '<=', '>='].includes(peek())) {
      const op = next();
      const r = parseAdditive();
      if (op === '<') left = left < r;
      else if (op === '>') left = left > r;
      else if (op === '<=') left = left <= r;
      else left = left >= r;
    }
    return left;
  }
  function parseAdditive() {
    let left = parseMultiplicative();
    while (peek() === '+' || peek() === '-') {
      const op = next();
      const r = parseMultiplicative();
      left = op === '+' ? left + r : left - r;
    }
    return left;
  }
  function parseMultiplicative() {
    let left = parseUnary();
    while (['*', '/', '%'].includes(peek())) {
      const op = next();
      const r = parseUnary();
      if (op === '*') left = left * r;
      else if (op === '/') left = left / r;
      else left = left % r;
    }
    return left;
  }
  function parseUnary() {
    if (peek() === '!') { next(); return !parseUnary(); }
    if (peek() === '-') { next(); return -parseUnary(); }
    return parsePrimary();
  }
  function parsePrimary() {
    const t = peek();
    if (t === undefined) throw new Error('Unexpected end of rule');
    if (t === '(') {
      next();
      const v = parseOr();
      if (next() !== ')') throw new Error('Expected )');
      return v;
    }
    if (/^[0-9]/.test(t)) { next(); return parseFloat(t); }
    if (t[0] === '"' || t[0] === "'") { next(); return t.slice(1, -1); }
    if (/^[A-Za-z_$]/.test(t)) {
      next();
      if (Object.prototype.hasOwnProperty.call(KEYWORDS, t)) return KEYWORDS[t];
      // identifier must be a property of the safe context (e.g. ctx)
      let value = Object.prototype.hasOwnProperty.call(ctx, t) ? ctx[t] : undefined;
      // member access chain: .prop  (bracket/computed access not allowed)
      while (peek() === '.') {
        next();
        const key = next();
        if (!/^[A-Za-z_$][A-Za-z0-9_$]*$/.test(key)) throw new Error('Invalid property access');
        // block prototype-pollution / escape vectors
        if (['__proto__', 'constructor', 'prototype'].includes(key)) {
          throw new Error('Forbidden property access');
        }
        value = value == null ? undefined : value[key];
      }
      return value;
    }
    throw new Error('Unexpected token: ' + t);
  }

  const result = parseOr();
  if (i !== tokens.length) throw new Error('Unexpected trailing tokens');
  return result;
}

// Evaluate a caller-supplied rule expression against the request context only.
function evalRule(req) {
  const expr = req.body && req.body.rule;        // e.g. 'ctx.amount > 100'
  if (typeof expr !== 'string') throw new Error('rule must be a string');
  if (expr.length > 1000) throw new Error('rule too long');
  const ctx = { ctx: (req.body && req.body.context) || {} }; // no `req` exposed
  return evaluate(expr, ctx);
}

app.post('/check', (req, res) => {
  try {
    const result = evalRule(req);
    res.json({ result: Boolean(result), value: result });
  } catch (err) {
    res.status(400).json({ error: 'Invalid rule', detail: err.message });
  }
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

