{
  "name": "acme-rules",
  "version": "1.0.0",
  "description": "Dynamic rule engine",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "test": "node test/check.test.js"
  },
  "dependencies": {
    "express": "^4.19.2"
  }
}

// Safe rule expression evaluator.
//
// SECURITY NOTE: The reference snippet in docs/RULES_ENGINE.md evaluates
// caller-supplied strings with `Function(...)` (equivalent to eval). That is a
// remote code execution vulnerability: an attacker can run arbitrary code via
// the request body. We deliberately do NOT do that. Instead we parse the rule
// into an AST and interpret it against a read-only context, supporting the
// documented use cases (e.g. `ctx.amount > 100 && ctx.country == "US"`).
//
// Supported grammar:
//   expr      := or
//   or        := and ( ('||') and )*
//   and       := equality ( ('&&') equality )*
//   equality  := comparison ( ('==' | '!=' | '===' | '!==') comparison )*
//   comparison:= additive ( ('<' | '<=' | '>' | '>=') additive )*
//   additive  := multiplicative ( ('+' | '-') multiplicative )*
//   multiplic := unary ( ('*' | '/' | '%') unary )*
//   unary     := ('!' | '-') unary | primary
//   primary   := number | string | boolean | null | member | '(' expr ')'
//   member    := identifier ( '.' identifier | '[' expr ']' )*
//
// Identifiers must resolve to an allowlisted root variable (default: `ctx`).
// No function calls, no assignment, no prototype access.

const ALLOWED_ROOTS = new Set(['ctx']);
// Block access to dangerous property names to avoid prototype pollution / escape.
const BLOCKED_KEYS = new Set([
  '__proto__', 'prototype', 'constructor',
]);

function tokenize(src) {
  const tokens = [];
  let i = 0;
  const isIdentStart = (c) => /[A-Za-z_$]/.test(c);
  const isIdentPart = (c) => /[A-Za-z0-9_$]/.test(c);

  while (i < src.length) {
    const c = src[i];

    if (/\s/.test(c)) { i++; continue; }

    // String literals
    if (c === '"' || c === "'") {
      const quote = c;
      let str = '';
      i++;
      while (i < src.length && src[i] !== quote) {
        if (src[i] === '\\') {
          const next = src[i + 1];
          const map = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', "'": "'" };
          str += Object.prototype.hasOwnProperty.call(map, next) ? map[next] : next;
          i += 2;
        } else {
          str += src[i++];
        }
      }
      if (src[i] !== quote) throw new SyntaxError('Unterminated string literal');
      i++;
      tokens.push({ type: 'string', value: str });
      continue;
    }

    // Numbers
    if (/[0-9]/.test(c) || (c === '.' && /[0-9]/.test(src[i + 1]))) {
      let num = '';
      while (i < src.length && /[0-9.]/.test(src[i])) num += src[i++];
      if ((num.match(/\./g) || []).length > 1) throw new SyntaxError('Invalid number: ' + num);
      tokens.push({ type: 'number', value: parseFloat(num) });
      continue;
    }

    // Identifiers / keywords
    if (isIdentStart(c)) {
      let id = '';
      while (i < src.length && isIdentPart(src[i])) id += src[i++];
      if (id === 'true') tokens.push({ type: 'boolean', value: true });
      else if (id === 'false') tokens.push({ type: 'boolean', value: false });
      else if (id === 'null') tokens.push({ type: 'null', value: null });
      else tokens.push({ type: 'ident', value: id });
      continue;
    }

    // Multi-char and single-char operators / punctuation
    const three = src.slice(i, i + 3);
    const two = src.slice(i, i + 2);
    if (three === '===' || three === '!==') { tokens.push({ type: 'op', value: three }); i += 3; continue; }
    if (['==', '!=', '<=', '>=', '&&', '||'].includes(two)) { tokens.push({ type: 'op', value: two }); i += 2; continue; }
    if ('+-*/%<>!().[]'.includes(c)) {
      const punct = '().[]';
      tokens.push({ type: punct.includes(c) ? 'punct' : 'op', value: c });
      i++;
      continue;
    }

    throw new SyntaxError('Unexpected character: ' + JSON.stringify(c));
  }

  tokens.push({ type: 'eof' });
  return tokens;
}

function parse(tokens) {
  let pos = 0;
  const peek = () => tokens[pos];
  const next = () => tokens[pos++];
  const expect = (value) => {
    const t = next();
    if (t.value !== value) throw new SyntaxError(`Expected ${value}`);
    return t;
  };
  const matchOp = (...ops) => {
    const t = peek();
    if ((t.type === 'op' || t.type === 'punct') && ops.includes(t.value)) { pos++; return t.value; }
    return null;
  };

  function parseExpr() { return parseOr(); }

  function parseOr() {
    let node = parseAnd();
    let op;
    while ((op = matchOp('||'))) node = { type: 'logical', op, left: node, right: parseAnd() };
    return node;
  }
  function parseAnd() {
    let node = parseEquality();
    let op;
    while ((op = matchOp('&&'))) node = { type: 'logical', op, left: node, right: parseEquality() };
    return node;
  }
  function parseEquality() {
    let node = parseComparison();
    let op;
    while ((op = matchOp('==', '!=', '===', '!=='))) node = { type: 'binary', op, left: node, right: parseComparison() };
    return node;
  }
  function parseComparison() {
    let node = parseAdditive();
    let op;
    while ((op = matchOp('<', '<=', '>', '>='))) node = { type: 'binary', op, left: node, right: parseAdditive() };
    return node;
  }
  function parseAdditive() {
    let node = parseMultiplicative();
    let op;
    while ((op = matchOp('+', '-'))) node = { type: 'binary', op, left: node, right: parseMultiplicative() };
    return node;
  }
  function parseMultiplicative() {
    let node = parseUnary();
    let op;
    while ((op = matchOp('*', '/', '%'))) node = { type: 'binary', op, left: node, right: parseUnary() };
    return node;
  }
  function parseUnary() {
    const op = matchOp('!', '-');
    if (op) return { type: 'unary', op, arg: parseUnary() };
    return parsePrimary();
  }
  function parsePrimary() {
    const t = peek();
    if (t.type === 'number' || t.type === 'string' || t.type === 'boolean' || t.type === 'null') {
      next();
      return { type: 'literal', value: t.value };
    }
    if (matchOp('(')) {
      const node = parseExpr();
      expect(')');
      return node;
    }
    if (t.type === 'ident') {
      next();
      if (!ALLOWED_ROOTS.has(t.value)) {
        throw new SyntaxError('Unknown identifier: ' + t.value);
      }
      let node = { type: 'identifier', name: t.value };
      // member access chain
      for (;;) {
        if (matchOp('.')) {
          const prop = next();
          if (prop.type !== 'ident') throw new SyntaxError('Expected property name after "."');
          node = { type: 'member', object: node, property: { type: 'literal', value: prop.value }, computed: false };
        } else if (matchOp('[')) {
          const prop = parseExpr();
          expect(']');
          node = { type: 'member', object: node, property: prop, computed: true };
        } else {
          break;
        }
      }
      return node;
    }
    throw new SyntaxError('Unexpected token: ' + (t.value !== undefined ? t.value : t.type));
  }

  const ast = parseExpr();
  if (peek().type !== 'eof') throw new SyntaxError('Unexpected trailing input');
  return ast;
}

function evaluate(node, scope) {
  switch (node.type) {
    case 'literal':
      return node.value;
    case 'identifier':
      return scope[node.name];
    case 'member': {
      const obj = evaluate(node.object, scope);
      if (obj == null) return undefined;
      const key = String(evaluate(node.property, scope));
      if (BLOCKED_KEYS.has(key)) throw new Error('Access to "' + key + '" is not allowed');
      // Only own enumerable data properties — never inherited/prototype members.
      if (!Object.prototype.hasOwnProperty.call(obj, key)) return undefined;
      return obj[key];
    }
    case 'unary': {
      const v = evaluate(node.arg, scope);
      if (node.op === '!') return !v;
      if (node.op === '-') return -v;
      break;
    }
    case 'logical': {
      const l = evaluate(node.left, scope);
      if (node.op === '&&') return l ? evaluate(node.right, scope) : l;
      if (node.op === '||') return l ? l : evaluate(node.right, scope);
      break;
    }
    case 'binary': {
      const l = evaluate(node.left, scope);
      const r = evaluate(node.right, scope);
      switch (node.op) {
        case '==': return l == r; // eslint-disable-line eqeqeq
        case '!=': return l != r; // eslint-disable-line eqeqeq
        case '===': return l === r;
        case '!==': return l !== r;
        case '<': return l < r;
        case '<=': return l <= r;
        case '>': return l > r;
        case '>=': return l >= r;
        case '+': return l + r;
        case '-': return l - r;
        case '*': return l * r;
        case '/': return l / r;
        case '%': return l % r;
      }
      break;
    }
  }
  throw new Error('Cannot evaluate node of type ' + node.type);
}

const MAX_RULE_LENGTH = 1000;

// Evaluate a caller-supplied rule expression against the request context.
// `context` is treated as untrusted, read-only data.
function evalRule(rule, context) {
  if (typeof rule !== 'string') throw new TypeError('rule must be a string');
  if (rule.length > MAX_RULE_LENGTH) throw new Error('rule expression too long');
  const ast = parse(tokenize(rule));
  const scope = { ctx: context == null ? {} : context };
  const result = evaluate(ast, scope);
  return Boolean(result);
}

module.exports = { evalRule, tokenize, parse };

