// Tests for the rule engine and POST /check behavior.
const assert = require('assert');
const { evalRule } = require('../ruleEngine');

let passed = 0;
function t(name, fn) {
  try { fn(); passed++; console.log('  ok  - ' + name); }
  catch (e) { console.error('FAIL  - ' + name + '\n        ' + e.message); process.exitCode = 1; }
}

// --- Functional: documented use cases ---
t('numeric comparison true', () => assert.strictEqual(evalRule('ctx.amount > 100', { amount: 150 }), true));
t('numeric comparison false', () => assert.strictEqual(evalRule('ctx.amount > 100', { amount: 50 }), false));
t('string equality', () => assert.strictEqual(evalRule('ctx.country == "US"', { country: 'US' }), true));
t('logical && / ||', () => assert.strictEqual(
  evalRule('ctx.amount > 100 && (ctx.country == "US" || ctx.vip)', { amount: 200, country: 'CA', vip: true }), true));
t('nested member access', () => assert.strictEqual(evalRule('ctx.user.age >= 18', { user: { age: 21 } }), true));
t('computed member access', () => assert.strictEqual(evalRule('ctx["amount"] == 5', { amount: 5 }), true));
t('arithmetic', () => assert.strictEqual(evalRule('ctx.a + ctx.b * 2 == 5', { a: 1, b: 2 }), true));
t('negation', () => assert.strictEqual(evalRule('!ctx.blocked', { blocked: false }), true));
t('missing prop is undefined (no throw)', () => assert.strictEqual(evalRule('ctx.nope > 1', {}), false));

// --- Security: must NOT allow code execution or escapes ---
function rejects(rule, ctx) {
  let threw = false;
  let escaped = false;
  try {
    const r = evalRule(rule, ctx || {});
    // If it evaluated, it must at least not return a dangerous/function value.
    if (typeof r !== 'boolean') escaped = true;
  } catch (_) { threw = true; }
  assert.ok(threw || !escaped, 'expression should be rejected or safely contained');
}

t('blocks function calls', () => {
  let threw = false;
  try { evalRule('ctx.toString()', {}); } catch (_) { threw = true; }
  assert.ok(threw, 'function calls must be a syntax error');
});
t('blocks process access (unknown identifier)', () => {
  let threw = false;
  try { evalRule('process.exit(1)', {}); } catch (_) { threw = true; }
  assert.ok(threw);
});
t('blocks require', () => {
  let threw = false;
  try { evalRule('require("child_process")', {}); } catch (_) { threw = true; }
  assert.ok(threw);
});
t('blocks constructor escape', () => {
  let threw = false;
  try { evalRule('ctx.constructor', { x: 1 }); } catch (e) { threw = true; }
  assert.ok(threw, 'constructor access must be blocked');
});
t('blocks __proto__ access', () => {
  let threw = false;
  try { evalRule('ctx.__proto__', {}); } catch (_) { threw = true; }
  assert.ok(threw);
});
t('does not leak inherited props', () => {
  // hasOwnProperty is on the prototype; must resolve to undefined, not the fn.
  assert.strictEqual(evalRule('ctx.hasOwnProperty == null', {}), true);
});
t('overlong rule rejected', () => {
  let threw = false;
  try { evalRule('1' + ' + 1'.repeat(1000), {}); } catch (_) { threw = true; }
  assert.ok(threw);
});

console.log(`\n${passed} checks passed.`);

