// --- Tokenizer ---------------------------------------------------------------
function tokenize(src) {
  const tokens = [];
  let i = 0;
  const isIdStart = (c) => /[A-Za-z_$]/.test(c);
  const isIdPart = (c) => /[A-Za-z0-9_$]/.test(c);
  while (i < src.length) {
    const c = src[i];
    if (/\s/.test(c)) { i++; continue; }

    // String literal
    if (c === '"' || c === "'") {
      const quote = c;
      let str = '';
      i++;
      while (i < src.length && src[i] !== quote) {
        if (src[i] === '\\') { str += src[i + 1]; i += 2; }
        else { str += src[i]; i++; }
      }
      if (src[i] !== quote) throw new Error('Unterminated string literal');
      i++;
      tokens.push({ type: 'string', value: str });
      continue;
    }

    // Number literal
    if (/[0-9]/.test(c) || (c === '.' && /[0-9]/.test(src[i + 1]))) {
      let num = '';
      while (i < src.length && /[0-9.]/.test(src[i])) { num += src[i]; i++; }
      tokens.push({ type: 'number', value: parseFloat(num) });
      continue;
    }

    // Identifier / keyword
    if (isIdStart(c)) {
      let id = '';
      while (i < src.length && isIdPart(src[i])) { id += src[i]; i++; }
      if (id === 'true' || id === 'false') tokens.push({ type: 'boolean', value: id === 'true' });
      else if (id === 'null') tokens.push({ type: 'null', value: null });
      else if (id === 'undefined') tokens.push({ type: 'undefined', value: undefined });
      else tokens.push({ type: 'identifier', value: id });
      continue;
    }

    // Multi-char operators
    const three = src.substr(i, 3);
    const two = src.substr(i, 2);
    if (['===', '!=='].includes(three)) { tokens.push({ type: 'op', value: three }); i += 3; continue; }
    if (['==', '!=', '>=', '<=', '&&', '||'].includes(two)) { tokens.push({ type: 'op', value: two }); i += 2; continue; }
    if ('><+-*/%!.()'.includes(c)) { tokens.push({ type: 'op', value: c }); i++; continue; }

