// documented use case (e.g. "ctx.amount > 100"): field lookups against the
// request context, comparisons, and boolean combinators — without executing
// arbitrary JavaScript.

const COMPARATORS = {
  '==': (a, b) => a === b,
  '!=': (a, b) => a !== b,
  '>': (a, b) => a > b,
  '>=': (a, b) => a >= b,
  '<': (a, b) => a < b,
  '<=': (a, b) => a <= b,
};

// Resolve a dotted path like "ctx.user.age" against { ctx }.
function resolvePath(path, scope) {
  return path.split('.').reduce((acc, key) => {
    if (acc == null) return undefined;
    return acc[key];
  }, scope);
}

// Parse a literal operand: number, quoted string, boolean, null, or a
// ctx.* path reference.
function resolveOperand(token, scope) {
  const t = token.trim();
  if (/^-?\d+(\.\d+)?$/.test(t)) return Number(t);
  if (/^'.*'$/.test(t) || /^".*"$/.test(t)) return t.slice(1, -1);
  if (t === 'true') return true;
  if (t === 'false') return false;
  if (t === 'null') return null;
