{
  "name": "acme-rules",
  "version": "1.0.0",
  "description": "Dynamic rule engine with a safe expression evaluator",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "test": "node test/check.test.js"
  },
  "dependencies": {
    "express": "^4.19.2"
  }
}

// Safe rule expression evaluator.
//
// NOTE: The reference in docs/RULES_ENGINE.md uses `Function(...)`/eval on a
// caller-supplied string. That is arbitrary remote code execution (RCE) and is
// intentionally NOT used here. This module instead parses a restricted
// expression grammar and evaluates it against a read-only context.
//
// Supported grammar:
//   expr      := or
//   or        := and ( ( "||" | "or" ) and )*
//   and       := not ( ( "&&" | "and" ) not )*
//   not       := ( "!" | "not" ) not | comparison
//   comparison:= sum ( ( "==" | "!=" | ">" | ">=" | "<" | "<=" ) sum )?
//   sum       := term ( ( "+" | "-" ) term )*
//   term      := factor ( ( "*" | "/" | "%" ) factor )*
//   factor    := NUMBER | STRING | BOOL | NULL | path | "(" expr ")"
//   path      := IDENT ( "." IDENT | "[" expr "]" )*
//
// Identifiers resolve against the supplied context object only. There is no
// access to functions, globals, prototypes, or Node internals.

const TOKEN = /\s*(>=|<=|==|!=|&&|\|\||[<>!+\-*/%().\[\]]|"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|[A-Za-z_$][A-Za-z0-9_$]*|\d+(?:\.\d+)?)\s*/y;

function tokenize(input) {
  const tokens = [];
  let pos = 0;
  while (pos < input.length) {
    TOKEN.lastIndex = pos;
    const m = TOKEN.exec(input);
    if (!m || m.index !== pos) {
      throw new RuleError(`Unexpected character at position ${pos}`);
    }
    tokens.push(m[1]);
    pos = TOKEN.lastIndex;
  }
  return tokens;
}

class RuleError extends Error {}

const KEYWORDS = { true: true, false: false, null: null };

function parse(tokens) {
  let i = 0;
  const peek = () => tokens[i];
  const next = () => tokens[i++];
  const eat = (t) => {
    if (tokens[i] !== t) throw new RuleError(`Expected "${t}"`);
    i++;
  };

  function parseExpr() {
    return parseOr();
  }

  function parseOr() {
    let node = parseAnd();
    while (peek() === '||' || peek() === 'or') {
      next();
      node = { type: 'or', left: node, right: parseAnd() };
    }
    return node;
  }

  function parseAnd() {
    let node = parseNot();
    while (peek() === '&&' || peek() === 'and') {
      next();
      node = { type: 'and', left: node, right: parseNot() };
    }
    return node;
  }

  function parseNot() {
    if (peek() === '!' || peek() === 'not') {
      next();
      return { type: 'not', value: parseNot() };
    }
    return parseComparison();
  }

  function parseComparison() {
    let node = parseSum();
    const op = peek();
    if (['==', '!=', '>', '>=', '<', '<='].includes(op)) {
      next();
      node = { type: 'cmp', op, left: node, right: parseSum() };
    }
    return node;
  }

  function parseSum() {
    let node = parseTerm();
    while (peek() === '+' || peek() === '-') {
      const op = next();
      node = { type: 'bin', op, left: node, right: parseTerm() };
    }
    return node;
  }

  function parseTerm() {
    let node = parseFactor();
    while (peek() === '*' || peek() === '/' || peek() === '%') {
      const op = next();
      node = { type: 'bin', op, left: node, right: parseFactor() };
    }
    return node;
  }

  function parseFactor() {
    const t = peek();
    if (t === undefined) throw new RuleError('Unexpected end of expression');

    if (t === '(') {
      next();
      const node = parseExpr();
      eat(')');
      return node;
    }
    // string literal
    if (t[0] === '"' || t[0] === "'") {
      next();
      return { type: 'lit', value: JSON.parse('"' + t.slice(1, -1).replace(/\\?"/g, '\\"') + '"') };
    }
    // number
    if (/^\d/.test(t)) {
      next();
      return { type: 'lit', value: Number(t) };
    }
    // identifier / keyword / path
    if (/^[A-Za-z_$]/.test(t)) {
      next();
      if (Object.prototype.hasOwnProperty.call(KEYWORDS, t)) {
        return { type: 'lit', value: KEYWORDS[t] };
      }
      let node = { type: 'var', name: t };
      while (peek() === '.' || peek() === '[') {
        if (next() === '.') {
          const key = next();
          if (!/^[A-Za-z_$][A-Za-z0-9_$]*$/.test(key)) {
            throw new RuleError(`Invalid property name "${key}"`);
          }
          node = { type: 'member', object: node, key: { type: 'lit', value: key } };
        } else {
          const key = parseExpr();
          eat(']');
          node = { type: 'member', object: node, key, computed: true };
        }
      }
      return node;
    }
    throw new RuleError(`Unexpected token "${t}"`);
  }

  const ast = parseExpr();
  if (i !== tokens.length) throw new RuleError(`Unexpected token "${tokens[i]}"`);
  return ast;
}

// Block access to dangerous keys so member access can't reach prototypes.
const FORBIDDEN_KEYS = new Set(['__proto__', 'prototype', 'constructor']);

function evaluate(node, ctx) {
  switch (node.type) {
    case 'lit':
      return node.value;
    case 'var': {
      if (FORBIDDEN_KEYS.has(node.name)) throw new RuleError(`Access to "${node.name}" is not allowed`);
      return ctx == null ? undefined : ctx[node.name];
    }
    case 'member': {
      const obj = evaluate(node.object, ctx);
      const key = evaluate(node.key, ctx);
      if (FORBIDDEN_KEYS.has(String(key))) throw new RuleError(`Access to "${key}" is not allowed`);
      if (obj == null) return undefined;
      // Only allow own enumerable properties of plain data objects/arrays.
      if (typeof obj !== 'object' && typeof obj !== 'string') return undefined;
      return obj[key];
    }
    case 'not':
      return !evaluate(node.value, ctx);
    case 'and':
      return evaluate(node.left, ctx) && evaluate(node.right, ctx);
    case 'or':
      return evaluate(node.left, ctx) || evaluate(node.right, ctx);
    case 'cmp': {
      const l = evaluate(node.left, ctx);
      const r = evaluate(node.right, ctx);
      switch (node.op) {
        case '==': return l === r;
        case '!=': return l !== r;
        case '>': return l > r;
        case '>=': return l >= r;
        case '<': return l < r;
        case '<=': return l <= r;
      }
      break;
    }
    case 'bin': {
      const l = evaluate(node.left, ctx);
      const r = evaluate(node.right, ctx);
      switch (node.op) {
        case '+': return l + r;
        case '-': return l - r;
        case '*': return l * r;
        case '/': return l / r;
        case '%': return l % r;
      }
      break;
    }
  }
  throw new RuleError(`Unknown node type "${node.type}"`);
}

/**
 * Safely evaluate a rule expression string against a context object.
 * Variables in the expression resolve against `context` (exposed as `ctx`).
 * Throws RuleError on invalid/unsupported expressions.
 */
function evalRule(expr, context) {
  if (typeof expr !== 'string') throw new RuleError('rule must be a string');
  if (expr.length > 1000) throw new RuleError('rule expression too long');
  const ast = parse(tokenize(expr));
  // The root context exposes only `ctx`; nothing else is reachable.
  return Boolean(evaluate(ast, { ctx: context ?? {} }));
}

module.exports = { evalRule, RuleError };

