const assert = require('assert');
const { evalRule, RuleError } = require('../ruleEngine');

const cases = [
  // [expr, context, expected]
  ['ctx.amount > 100', { amount: 150 }, true],
  ['ctx.amount > 100', { amount: 50 }, false],
  ["ctx.amount > 100 && ctx.country == 'US'", { amount: 150, country: 'US' }, true],
  ["ctx.amount > 100 && ctx.country == 'US'", { amount: 150, country: 'CA' }, false],
  ['ctx.a + ctx.b >= 10', { a: 4, b: 7 }, true],
  ['!ctx.flag', { flag: false }, true],
  ['ctx.user.role == "admin"', { user: { role: 'admin' } }, true],
  ["ctx.items[0] == 'x'", { items: ['x'] }, true],
  ['ctx.missing > 1', {}, false],
  ['(ctx.a > 1 or ctx.b > 1) and not ctx.c', { a: 5, b: 0, c: false }, true],
];

for (const [expr, ctx, expected] of cases) {
  const got = evalRule(expr, ctx);
  assert.strictEqual(got, expected, `evalRule(${JSON.stringify(expr)}) => ${got}, expected ${expected}`);
}

// Injection / RCE attempts must be rejected (parse errors), never executed.
const malicious = [
  "require('child_process').execSync('id')",
  'process.exit(1)',
  'this.constructor.constructor("return process")()',
  'ctx.constructor',
  'ctx.__proto__',
  '() => 1',
  'global',
];

for (const expr of malicious) {
  let threw = false;
  try {
    const r = evalRule(expr, {});
    // If it parsed, it must NOT have reached anything dangerous; result is boolean.
    assert.strictEqual(typeof r, 'boolean');
    // 'ctx.constructor' style access must throw rather than return a function.
  } catch (e) {
    threw = true;
    assert.ok(e instanceof RuleError, `expected RuleError for ${expr}, got ${e}`);
  }
}

// Explicitly ensure prototype/constructor access throws.
for (const expr of ['ctx.constructor', 'ctx.__proto__', 'ctx["constructor"]']) {
  assert.throws(() => evalRule(expr, {}), RuleError, `should block ${expr}`);
}

console.log('All rule engine tests passed.');

