// Safe rule expression evaluator.
//
// SECURITY NOTE: The reference snippet in docs/RULES_ENGINE.md evaluates
// caller-supplied strings via `Function(...)` (i.e. eval). That is a remote
// code execution vulnerability: any client could run arbitrary code on the
// server. This module deliberately replaces that approach with a small,
// sandboxed expression evaluator that supports the same feature (evaluating
// a rule against a request context) WITHOUT exposing eval, the filesystem,
// globals, or the raw request object.
//
// Supported grammar:
//   expr     := or
//   or       := and ( ('||') and )*
//   and      := not ( ('&&') not )*
//   not      := '!' not | comparison
//   comparison := add ( ('==' | '!=' | '<' | '<=' | '>' | '>=') add )?
//   add      := mul ( ('+' | '-') mul )*
//   mul      := unary ( ('*' | '/' | '%') unary )*
//   unary    := '-' unary | primary
//   primary  := number | string | true | false | null
//             | identifier ( '.' identifier | '[' expr ']' )*
//             | '(' expr ')'
//
// Identifiers resolve ONLY against the provided context object. There is no
// access to function calls, prototypes, or the global scope.

class Tokenizer {
  constructor(input) {
    this.input = input;
    this.pos = 0;
    this.tokens = [];
  }

  static OPERATORS = ['===', '!==', '==', '!=', '<=', '>=', '&&', '||', '<', '>', '+', '-', '*', '/', '%', '!', '(', ')', '[', ']', '.'];

  tokenize() {
    const s = this.input;
    while (this.pos < s.length) {
      const c = s[this.pos];

      if (/\s/.test(c)) { this.pos++; continue; }

      // String literal
      if (c === '"' || c === "'") {
        this.pos++;
        let str = '';
        while (this.pos < s.length && s[this.pos] !== c) {
          if (s[this.pos] === '\\') { str += s[this.pos + 1]; this.pos += 2; }
          else { str += s[this.pos]; this.pos++; }
        }
        if (this.pos >= s.length) throw new Error('Unterminated string literal');
        this.pos++; // closing quote
        this.tokens.push({ type: 'string', value: str });
        continue;
      }

      // Number literal
      if (/[0-9]/.test(c) || (c === '.' && /[0-9]/.test(s[this.pos + 1]))) {
        let num = '';
        while (this.pos < s.length && /[0-9.]/.test(s[this.pos])) { num += s[this.pos]; this.pos++; }
        this.tokens.push({ type: 'number', value: parseFloat(num) });
        continue;
      }

      // Identifier / keyword
      if (/[A-Za-z_$]/.test(c)) {
        let id = '';
        while (this.pos < s.length && /[A-Za-z0-9_$]/.test(s[this.pos])) { id += s[this.pos]; this.pos++; }
        if (id === 'true') this.tokens.push({ type: 'boolean', value: true });
        else if (id === 'false') this.tokens.push({ type: 'boolean', value: false });
        else if (id === 'null') this.tokens.push({ type: 'null', value: null });
        else this.tokens.push({ type: 'identifier', value: id });
        continue;
      }

      // Operators / punctuation
      const op = Tokenizer.OPERATORS.find((o) => s.startsWith(o, this.pos));
      if (op) { this.tokens.push({ type: 'operator', value: op }); this.pos += op.length; continue; }

      throw new Error(`Unexpected character '${c}' at position ${this.pos}`);
    }
    return this.tokens;
  }
}

class Parser {
  constructor(tokens) { this.tokens = tokens; this.pos = 0; }

  peek() { return this.tokens[this.pos]; }
  next() { return this.tokens[this.pos++]; }
  expectOp(op) {
    const t = this.next();
    if (!t || t.type !== 'operator' || t.value !== op) throw new Error(`Expected '${op}'`);
  }
  matchOp(...ops) {
    const t = this.peek();
    if (t && t.type === 'operator' && ops.includes(t.value)) { this.pos++; return t.value; }
    return null;
  }

  parse() {
    const node = this.parseOr();
    if (this.pos < this.tokens.length) throw new Error('Unexpected trailing tokens');
    return node;
  }

  parseOr() {
    let left = this.parseAnd();
    let op;
    while ((op = this.matchOp('||'))) left = { type: 'logical', op, left, right: this.parseAnd() };
    return left;
  }

  parseAnd() {
    let left = this.parseNot();
    let op;
    while ((op = this.matchOp('&&'))) left = { type: 'logical', op, left, right: this.parseNot() };
    return left;
  }

  parseNot() {
    if (this.matchOp('!')) return { type: 'unary', op: '!', arg: this.parseNot() };
    return this.parseComparison();
  }

  parseComparison() {
    let left = this.parseAdd();
    const op = this.matchOp('===', '!==', '==', '!=', '<=', '>=', '<', '>');
    if (op) return { type: 'binary', op, left, right: this.parseAdd() };
    return left;
  }

  parseAdd() {
    let left = this.parseMul();
    let op;
    while ((op = this.matchOp('+', '-'))) left = { type: 'binary', op, left, right: this.parseMul() };
    return left;
  }

  parseMul() {
    let left = this.parseUnary();
    let op;
    while ((op = this.matchOp('*', '/', '%'))) left = { type: 'binary', op, left, right: this.parseUnary() };
    return left;
  }

  parseUnary() {
    if (this.matchOp('-')) return { type: 'unary', op: '-', arg: this.parseUnary() };
    return this.parsePrimary();
  }

  parsePrimary() {
    const t = this.peek();
    if (!t) throw new Error('Unexpected end of expression');

    if (t.type === 'operator' && t.value === '(') {
      this.next();
      const node = this.parseOr();
      this.expectOp(')');
      return node;
    }

    if (['number', 'string', 'boolean', 'null'].includes(t.type)) {
      this.next();
      return { type: 'literal', value: t.value };
    }

    if (t.type === 'identifier') {
      this.next();
      let node = { type: 'identifier', name: t.value };
      // member access chain
      for (;;) {
        if (this.matchOp('.')) {
          const prop = this.next();
          if (!prop || prop.type !== 'identifier') throw new Error('Expected property name after "."');
          node = { type: 'member', object: node, property: { type: 'literal', value: prop.value } };
        } else if (this.matchOp('[')) {
          const idx = this.parseOr();
          this.expectOp(']');
          node = { type: 'member', object: node, property: idx };
        } else break;
      }
      return node;
    }

    throw new Error(`Unexpected token '${t.value}'`);
  }
}

const FORBIDDEN_KEYS = new Set(['__proto__', 'prototype', 'constructor']);

function evaluate(node, ctx) {
  switch (node.type) {
    case 'literal':
      return node.value;

    case 'identifier':
      if (node.name === 'ctx') return ctx;
      // Allow top-level identifiers to resolve against ctx directly too.
      return ctx == null ? undefined : ctx[node.name];

    case 'member': {
      const obj = evaluate(node.object, ctx);
      const key = evaluate(node.property, ctx);
      if (obj == null) return undefined;
      if (FORBIDDEN_KEYS.has(String(key))) throw new Error(`Access to '${key}' is not allowed`);
      // Only read own/enumerable-style data, never functions.
      const val = obj[key];
      if (typeof val === 'function') throw new Error('Function access is not allowed');
      return val;
    }

    case 'unary': {
      const v = evaluate(node.arg, ctx);
      if (node.op === '!') return !v;
      if (node.op === '-') return -v;
      throw new Error(`Unknown unary operator ${node.op}`);
    }

    case 'logical': {
      const l = evaluate(node.left, ctx);
      if (node.op === '&&') return l ? evaluate(node.right, ctx) : l;
      if (node.op === '||') return l ? l : evaluate(node.right, ctx);
      throw new Error(`Unknown logical operator ${node.op}`);
    }

    case 'binary': {
      const l = evaluate(node.left, ctx);
      const r = evaluate(node.right, ctx);
      switch (node.op) {
        case '==': return l == r; // eslint-disable-line eqeqeq
        case '!=': return l != r; // eslint-disable-line eqeqeq
        case '===': return l === r;
        case '!==': return l !== r;
        case '<': return l < r;
        case '<=': return l <= r;
        case '>': return l > r;
        case '>=': return l >= r;
        case '+': return l + r;
        case '-': return l - r;
        case '*': return l * r;
        case '/': return l / r;
        case '%': return l % r;
        default: throw new Error(`Unknown operator ${node.op}`);
      }
    }

    default:
      throw new Error(`Unknown node type ${node.type}`);
  }
}

const MAX_EXPR_LENGTH = 1000;

/**
 * Safely evaluate a rule expression against a context object.
 * @param {string} expr  e.g. "ctx.amount > 100 && ctx.country == 'US'"
 * @param {object} context  arbitrary data object
 * @returns {boolean} truthiness of the evaluated expression
 */
function evalRule(expr, context) {
  if (typeof expr !== 'string') throw new Error('rule must be a string');
  if (expr.length > MAX_EXPR_LENGTH) throw new Error('rule expression too long');
  const tokens = new Tokenizer(expr).tokenize();
  const ast = new Parser(tokens).parse();
  const result = evaluate(ast, context ?? {});
  return Boolean(result);
}

module.exports = { evalRule };

