{
  "name": "acme-rules",
  "version": "1.0.0",
  "description": "Dynamic rule engine with a safe expression evaluator",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "test": "node test/safeEval.test.js"
  },
  "dependencies": {
    "express": "^4.19.2"
  }
}

'use strict';

// safeEval — a small, sandboxed expression evaluator for rule checks.
//
// SECURITY NOTE:
// The reference snippet in docs/RULES_ENGINE.md uses `Function(...)` to run a
// caller-supplied string. That is a remote-code-execution (RCE) vulnerability:
// a client could call process.exit(), spawn child processes, read process.env,
// touch the filesystem, etc. We deliberately do NOT do that.
//
// Instead we parse the expression into an AST and evaluate only a safe subset:
//   - literals: numbers, strings, true/false/null
//   - member access against the provided context (e.g. ctx.amount, ctx.user.role)
//   - comparisons: === !== == != < <= > >=
//   - boolean logic: && || ! and parentheses
//   - arithmetic: + - * / %
// There is no function calling, no property assignment, and no access to any
// global object — only the data passed in `context` is reachable.

// ---- Tokenizer ----------------------------------------------------------

const TOKEN_REGEX = [
  ['WS', /^\s+/],
  ['NUMBER', /^\d+(\.\d+)?/],
  ['STRING', /^'(\\.|[^'\\])*'|^"(\\.|[^"\\])*"/],
  ['OP', /^(===|!==|==|!=|<=|>=|&&|\|\||[<>+\-*/%!()\.])/],
  ['IDENT', /^[A-Za-z_$][A-Za-z0-9_$]*/],
];

function tokenize(input) {
  const tokens = [];
  let s = input;
  while (s.length > 0) {
    let matched = false;
    for (const [type, regex] of TOKEN_REGEX) {
      const m = regex.exec(s);
      if (m) {
        matched = true;
        s = s.slice(m[0].length);
        if (type !== 'WS') tokens.push({ type, value: m[0] });
        break;
      }
    }
    if (!matched) {
      throw new SyntaxError(`Unexpected token near: ${s.slice(0, 16)}`);
    }
  }
  return tokens;
}

// ---- Parser (recursive descent, precedence climbing) --------------------
//
// Grammar (lowest to highest precedence):
//   or      := and ('||' and)*
//   and     := equality ('&&' equality)*
//   equality:= comparison (('=='|'!='|'==='|'!==') comparison)*
//   comparison := additive (('<'|'<='|'>'|'>=') additive)*
//   additive:= multiplicative (('+'|'-') multiplicative)*
//   multiplicative := unary (('*'|'/'|'%') unary)*
//   unary   := '!' unary | primary
//   primary := NUMBER | STRING | IDENT member* | '(' or ')'
//   member  := '.' IDENT

function parse(tokens) {
  let pos = 0;

  const peek = () => tokens[pos];
  const next = () => tokens[pos++];
  const expect = (value) => {
    const t = next();
    if (!t || t.value !== value) {
      throw new SyntaxError(`Expected '${value}'`);
    }
    return t;
  };

  function parseOr() {
    let left = parseAnd();
    while (peek() && peek().value === '||') {
      next();
      left = { type: 'Logical', op: '||', left, right: parseAnd() };
    }
    return left;
  }

  function parseAnd() {
    let left = parseEquality();
    while (peek() && peek().value === '&&') {
      next();
      left = { type: 'Logical', op: '&&', left, right: parseEquality() };
    }
    return left;
  }

  function parseEquality() {
    let left = parseComparison();
    while (peek() && ['==', '!=', '===', '!=='].includes(peek().value)) {
      const op = next().value;
      left = { type: 'Binary', op, left, right: parseComparison() };
    }
    return left;
  }

  function parseComparison() {
    let left = parseAdditive();
    while (peek() && ['<', '<=', '>', '>='].includes(peek().value)) {
      const op = next().value;
      left = { type: 'Binary', op, left, right: parseAdditive() };
    }
    return left;
  }

  function parseAdditive() {
    let left = parseMultiplicative();
    while (peek() && ['+', '-'].includes(peek().value)) {
      const op = next().value;
      left = { type: 'Binary', op, left, right: parseMultiplicative() };
    }
    return left;
  }

  function parseMultiplicative() {
    let left = parseUnary();
    while (peek() && ['*', '/', '%'].includes(peek().value)) {
      const op = next().value;
      left = { type: 'Binary', op, left, right: parseUnary() };
    }
    return left;
  }

  function parseUnary() {
    if (peek() && peek().value === '!') {
      next();
      return { type: 'Unary', op: '!', arg: parseUnary() };
    }
    return parsePrimary();
  }

  function parsePrimary() {
    const t = peek();
    if (!t) throw new SyntaxError('Unexpected end of expression');

    if (t.value === '(') {
      next();
      const expr = parseOr();
      expect(')');
      return expr;
    }

    if (t.type === 'NUMBER') {
      next();
      return { type: 'Literal', value: Number(t.value) };
    }

    if (t.type === 'STRING') {
      next();
      // strip quotes and unescape
      const raw = t.value.slice(1, -1).replace(/\\(.)/g, '$1');
      return { type: 'Literal', value: raw };
    }

    if (t.type === 'IDENT') {
      next();
      if (t.value === 'true') return { type: 'Literal', value: true };
      if (t.value === 'false') return { type: 'Literal', value: false };
      if (t.value === 'null') return { type: 'Literal', value: null };

      let node = { type: 'Identifier', name: t.value };
      while (peek() && peek().value === '.') {
        next();
        const prop = next();
        if (!prop || prop.type !== 'IDENT') {
          throw new SyntaxError('Expected property name after "."');
        }
        node = { type: 'Member', object: node, property: prop.value };
      }
      return node;
    }

    throw new SyntaxError(`Unexpected token '${t.value}'`);
  }

  const ast = parseOr();
  if (pos !== tokens.length) {
    throw new SyntaxError(`Unexpected token '${tokens[pos].value}'`);
  }
  return ast;
}

// ---- Evaluator ----------------------------------------------------------

// Block access to dangerous property names even on plain data objects.
const FORBIDDEN_PROPS = new Set([
  '__proto__',
  'prototype',
  'constructor',
]);

function evaluate(node, scope) {
  switch (node.type) {
    case 'Literal':
      return node.value;

    case 'Identifier': {
      if (!Object.prototype.hasOwnProperty.call(scope, node.name)) {
        throw new ReferenceError(`Unknown identifier '${node.name}'`);
      }
      return scope[node.name];
    }

    case 'Member': {
      const obj = evaluate(node.object, scope);
      if (obj == null) return undefined;
      if (FORBIDDEN_PROPS.has(node.property)) {
        throw new Error(`Access to '${node.property}' is not allowed`);
      }
      // Only read own enumerable-ish data properties; never inherited methods.
      if (!Object.prototype.hasOwnProperty.call(Object(obj), node.property)) {
        return undefined;
      }
      const value = obj[node.property];
      if (typeof value === 'function') {
        throw new Error('Calling or accessing functions is not allowed');
      }
      return value;
    }

    case 'Unary':
      return !evaluate(node.arg, scope);

    case 'Logical': {
      const left = evaluate(node.left, scope);
      if (node.op === '&&') return left && evaluate(node.right, scope);
      return left || evaluate(node.right, scope);
    }

    case 'Binary': {
      const l = evaluate(node.left, scope);
      const r = evaluate(node.right, scope);
      switch (node.op) {
        case '===': return l === r;
        case '!==': return l !== r;
        case '==': return l == r; // eslint-disable-line eqeqeq
        case '!=': return l != r; // eslint-disable-line eqeqeq
        case '<': return l < r;
        case '<=': return l <= r;
        case '>': return l > r;
        case '>=': return l >= r;
        case '+': return l + r;
        case '-': return l - r;
        case '*': return l * r;
        case '/': return l / r;
        case '%': return l % r;
        default: throw new Error(`Unsupported operator '${node.op}'`);
      }
    }

    default:
      throw new Error(`Unsupported node type '${node.type}'`);
  }
}

// Compiled-rule cache so repeated rules don't re-parse every request.
const cache = new Map();
const MAX_RULE_LENGTH = 1000;

/**
 * Safely evaluate a rule expression against a data context.
 * @param {string} expr  The rule expression, e.g. "ctx.amount > 100".
 * @param {object} context  Data made available as `ctx` in the expression.
 * @returns {*} The result of the expression (typically a boolean).
 */
function safeEval(expr, context) {
  if (typeof expr !== 'string') {
    throw new TypeError('rule must be a string');
  }
  if (expr.length > MAX_RULE_LENGTH) {
    throw new RangeError('rule expression is too long');
  }

  let ast = cache.get(expr);
  if (!ast) {
    ast = parse(tokenize(expr));
    cache.set(expr, ast);
  }

  const scope = { ctx: context == null ? {} : context };
  return evaluate(ast, scope);
}

module.exports = { safeEval };

