'use strict';

const assert = require('assert');
const { safeEval } = require('../safeEval');

let passed = 0;
function check(name, fn) {
  try {
    fn();
    passed++;
    console.log(`  ok  - ${name}`);
  } catch (err) {
    console.error(`  FAIL- ${name}: ${err.message}`);
    process.exitCode = 1;
  }
}

// --- functional behaviour ---
check('numeric comparison', () => {
  assert.strictEqual(safeEval('ctx.amount > 100', { amount: 150 }), true);
  assert.strictEqual(safeEval('ctx.amount > 100', { amount: 50 }), false);
});

check('string equality', () => {
  assert.strictEqual(safeEval("ctx.user.role === 'admin'", { user: { role: 'admin' } }), true);
});

check('boolean logic and precedence', () => {
  assert.strictEqual(
    safeEval('ctx.a > 1 && (ctx.b === 2 || ctx.c)', { a: 5, b: 0, c: true }),
    true
  );
});

check('arithmetic', () => {
  assert.strictEqual(safeEval('ctx.x * 2 + 1', { x: 3 }), 7);
});

check('missing properties resolve to undefined', () => {
  assert.strictEqual(safeEval('ctx.nope > 1', {}), false);
});

// --- security: these MUST throw, never execute ---
check('blocks process access', () => {
  assert.throws(() => safeEval('process.exit(1)', {}));
});

check('blocks require/child_process', () => {
  assert.throws(() => safeEval("require('child_process')", {}));
});

check('blocks constructor escape', () => {
  assert.throws(() => safeEval("ctx.constructor", { x: 1 }));
  assert.throws(() => safeEval("ctx.__proto__", { x: 1 }));
});

check('blocks function calls', () => {
  assert.throws(() => safeEval("ctx.toString()", { x: 1 }));
});

check('blocks accessing inherited methods', () => {
  assert.throws(() => safeEval('ctx.hasOwnProperty', { x: 1 }));
});

check('rejects non-string rules', () => {
  assert.throws(() => safeEval(42, {}));
});

console.log(`\n${passed} checks passed.`);

