// Allowed comparison/logical operators for the safe rule evaluator.
const OPERATORS = {
  '>': (a, b) => a > b,
  '>=': (a, b) => a >= b,
  '<': (a, b) => a < b,
  '<=': (a, b) => a <= b,
  '==': (a, b) => a === b,
  '!=': (a, b) => a !== b,
};

// Resolve a dotted path like "ctx.amount" against the context object.
// Only plain own-property access is allowed; prototype access is blocked.
function resolvePath(path, ctx) {
  const parts = path.split('.');
  let current = { ctx };
  for (const part of parts) {
    if (
      current == null ||
      typeof current !== 'object' ||
      !Object.prototype.hasOwnProperty.call(current, part)
    ) {
      return undefined;
    }
    current = current[part];
  }
  return current;
}

// Parse a literal token: number, quoted string, boolean, or null.
function parseLiteral(token) {
  if (/^-?\d+(\.\d+)?$/.test(token)) return Number(token);
  if (/^"[^"]*"$/.test(token) || /^'[^']*'$/.test(token)) {
    return token.slice(1, -1);
  }
  if (token === 'true') return true;
  if (token === 'false') return false;
  if (token === 'null') return null;
  return undefined; // signal "not a literal"
}

// Resolve an operand: either a literal value or a path into the context.
function resolveOperand(token, ctx) {
  const literal = parseLiteral(token);
  if (literal !== undefined) return literal;
  if (/^[a-zA-Z_][\w.]*$/.test(token)) return resolvePath(token, ctx);
  throw new Error(`Invalid operand: ${token}`);
}

// Safely evaluate a single comparison clause, e.g. "ctx.amount > 100".
function evalClause(clause, ctx) {
  // Match: <operand> <op> <operand>
  const m = clause
    .trim()
    .match(/^(.+?)\s*(>=|<=|==|!=|>|<)\s*(.+)$/);
  if (!m) throw new Error(`Invalid rule clause: ${clause}`);
